import { produce } from 'immer';

const baseState = [
  { title: "Learn React", done: true },
  { title: "Learn Redux", done: false }
]

// How Immer works (This is exactly what RTK does inside createSlice)
const nextState = produce(baseState, draftState => {
  // We can push to the array! (Normally forbidden in Redux)
  draftState.push({ title: "Learn Immer", done: false });

  // We can reassign properties directly!
  draftState[1].done = true;
});

// baseState is perfectly untouched! Immutable rules are preserved.
